var b = ($json && $json.body) ? $json.body : ($json || {});
var name = b.business_name || 'My Business';
var tagline = b.tagline || '';
var servicesRaw = b.services;
var services = '';
if (Array.isArray(servicesRaw)) { services = servicesRaw.filter(function(s){ return s !== null && s !== undefined && String(s).trim(); }).map(function(s){ return String(s).trim(); }).join(', '); }
else { services = servicesRaw ? String(servicesRaw) : ''; }
var logoUrl = b.logo_url || '';
var colorPref = b.color_preference || '';
var brandHex = '';
if (b.brand_hex_color && String(b.brand_hex_color).trim()) {
  var bh = String(b.brand_hex_color).trim();
  if (bh.charAt(0) !== '#') { bh = '#' + bh; }
  if (/^#[0-9a-fA-F]{3}([0-9a-fA-F]{3})?$/.test(bh)) { brandHex = bh; }
}
var menuRaw = b.menu_photo_urls;
var menuPhotos = [];
if (Array.isArray(menuRaw)) { menuPhotos = menuRaw; }
else if (menuRaw && String(menuRaw).trim()) { menuPhotos = String(menuRaw).split(','); }
menuPhotos = menuPhotos.map(function(u){ return String(u == null ? '' : u).trim(); }).filter(function(u){ return u.length > 0; });
var socialRaw = (b.social_links && typeof b.social_links === 'object' && !Array.isArray(b.social_links)) ? b.social_links : {};
var socialLinks = {};
var socialParts = [];
var socialKeys = Object.keys(socialRaw);
for (var i = 0; i < socialKeys.length; i++) {
  var k = socialKeys[i];
  var v = socialRaw[k];
  if (v && String(v).trim()) { socialLinks[k] = String(v).trim(); socialParts.push(k + ': ' + String(v).trim()); }
}
var accent = brandHex || colorPref || '';
var descParts = [];
if (accent) descParts.push('Preferred brand/accent color: ' + accent + '.');
if (logoUrl) descParts.push('Use this logo image at the top of the page: ' + logoUrl + '.');
if (menuPhotos.length) descParts.push('Include a menu gallery section rendering these ' + menuPhotos.length + ' menu photos.');
if (socialParts.length) descParts.push('Add social media links in the footer.');
var description = descParts.join(' ');
var sys = 'You are an expert web designer and front-end developer. Generate a COMPLETE, professional, production-ready single-file HTML web page for the given business. Requirements: valid HTML5 document starting with <!DOCTYPE html>; all CSS embedded in a <style> tag and all JavaScript embedded in a <script> tag (no external build steps, though loading fonts/icons from a public CDN is allowed); mobile-responsive layout using modern CSS (Grid/Flexbox, CSS variables); include a hero section with the business name and tagline, a services/features section, an about section, and a contact/footer section; use contextual, industry-appropriate real copy (never Lorem Ipsum); include SEO meta tags and accessibility attributes; tasteful animations. If a logo URL is provided, place it in the header. If a brand/accent color is provided, use it as the primary brand color (as a CSS variable) overriding any default. If menu photo URLs are provided, add a dedicated "Menu" gallery section that renders each photo as a responsive <img> in a CSS grid with lazy loading and alt text. If social media links are provided, render matching social icons/links in the footer. Only include sections for which data is actually provided; when a field is absent, do not mention or fabricate it. Output ONLY the raw HTML document. Do not wrap it in markdown code fences, do not add any commentary before or after.';
var usr = 'Business Name: ' + name + '\nTagline: ' + tagline + '\nServices: ' + services;
if (logoUrl) usr += '\nLogo URL (place in header): ' + logoUrl;
if (accent) usr += '\nBrand/Accent Color (use as primary, override default): ' + accent;
if (menuPhotos.length) usr += '\nMenu Photo URLs (render as a responsive gallery section):\n- ' + menuPhotos.join('\n- ');
if (socialParts.length) usr += '\nSocial Links (render as icons in footer):\n- ' + socialParts.join('\n- ');
if (description) usr += '\nNotes: ' + description;
var slug = String(name).toLowerCase().trim().replace(/[\u2019'".]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
return [{ json: { business_name: name, tagline: tagline, services: services, logo_url: logoUrl, color_preference: colorPref, brand_hex_color: brandHex, menu_photo_urls: menuPhotos, social_links: socialLinks, description: description, slug: slug, sys: sys, usr: usr } }];

var prep = $('Prep Site').first().json || {};
var src = $input.first().json || {};
var raw = String(src.text || '');
var source = src.provider_used || src.provider || 'hub';
function clean(s){ s=String(s||'').trim(); if(s.indexOf('```')!==-1){ s=s.replace(/```html/gi,'').replace(/```/g,'').trim(); } return s; }
var c = clean(raw); var lc = c.toLowerCase();
var ok = (lc.indexOf('<html')!==-1 || lc.indexOf('<!doctype')!==-1) && c.length>=120;
return [{ json: { business_name: prep.business_name, slug: prep.slug, html: ok?c:'', ai_source: ok?source:'none', html_ok: ok } }];

var m = $input.first().json || {};
var prep = $('Prep Site').first().json || {};
var name = prep.business_name || m.business_name || 'My Business';
var slug = prep.slug || m.slug || 'site';
var tagline = prep.tagline || '';
var services = prep.services || '';
var html = String(m.html || '').trim();
var source = m.ai_source || 'none';
var lc = html.toLowerCase();
var valid = (lc.indexOf('<html')!==-1 || lc.indexOf('<!doctype')!==-1) && html.length >= 120;
if (!valid) {
  var svcItems = String(services).split(',').map(function(s){ return s.trim(); }).filter(function(s){ return s.length; });
  var svcHtml = svcItems.length ? svcItems.map(function(s){ return '<li>' + s + '</li>'; }).join('') : '<li>Quality products and services</li>';
  html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="description" content="' + name + ' - ' + tagline + '"><title>' + name + '</title><style>:root{--brand:#b5651d}*{box-sizing:border-box;margin:0;padding:0}body{font-family:system-ui,Segoe UI,Roboto,sans-serif;color:#222;line-height:1.6}header{background:var(--brand);color:#fff;text-align:center;padding:80px 20px}header h1{font-size:2.5rem}header p{font-size:1.25rem;margin-top:10px}main{max-width:900px;margin:0 auto;padding:40px 20px}section{margin-bottom:40px}h2{color:var(--brand);margin-bottom:15px}ul{list-style:none;display:grid;gap:12px}li{background:#f7f2ec;padding:14px 18px;border-radius:8px}footer{background:#222;color:#fff;text-align:center;padding:30px 20px}</style></head><body><header><h1>' + name + '</h1><p>' + tagline + '</p></header><main><section><h2>Our Services</h2><ul>' + svcHtml + '</ul></section><section><h2>About Us</h2><p>Welcome to ' + name + '. ' + tagline + '. We are dedicated to delivering the very best to our community every day.</p></section></main><footer><p>&copy; ' + name + '. Get in touch to learn more.</p></footer></body></html>';
  source = 'hardcoded_fallback';
}
return [{ json: { business_name: name, slug: slug, ai_source: source, file_path: 'sites/' + slug + '/index.html', live_url: 'https://hsndm.tech/sites/' + slug + '/', html: html } }];

var fin = $('Finalize HTML').first().json || {};
var shaResp = $input.first().json || {};
var sha = '';
try { if (shaResp && typeof shaResp.sha === 'string' && shaResp.sha.length) sha = shaResp.sha; } catch (e) { sha = ''; }
var contentB64 = Buffer.from(String(fin.html || ''), 'utf8').toString('base64');
var body = { message: 'Add generated site for ' + (fin.business_name || 'site') + ' (AI: ' + (fin.ai_source || 'none') + ')', content: contentB64 };
if (sha) { body.sha = sha; }
return [{ json: { business_name: fin.business_name, slug: fin.slug, ai_source: fin.ai_source, file_path: fin.file_path, live_url: fin.live_url, sha: sha, existed: !!sha, putUrl: 'https://api.github.com/repos/hsndm566/hsndm.tech/contents/' + fin.file_path, putBody: body } }];

const pages = $("Build Pages").all();
const verify = $("Verify Live").all();
const out = [];
for (let i = 0; i < pages.length; i++) {
  const v = verify[i] ? verify[i].json : {};
  const status = (v.statusCode !== undefined) ? v.statusCode : (v.error ? "error" : "unknown");
  out.push({ json: { filename: pages[i].json.filename, url: "https://hsndm.tech/" + pages[i].json.filename, live_http_status: status, is_live: status === 200 } });
}
return out;

return [
  { json: { filename: "index.html" } },
  { json: { filename: "dashboard.html" } },
  { json: { filename: "cv.html" } },
];

const api = $json;
const filename = api.name || api.path;
const raw = (api.content || "").replace(/\n/g, "");
let html = Buffer.from(raw, "base64").toString("utf8");

const widget = [
  '<div id="google_translate_element" style="position:fixed; top:10px; right:10px; z-index:70;"></div>',
  '<script>',
  String.fromCharCode(32,32) + "function googleTranslateElementInit() {",
  String.fromCharCode(32,32,32,32) + "new google.translate.TranslateElement({",
  String.fromCharCode(32,32,32,32,32,32) + "pageLanguage: " + String.fromCharCode(39) + "en" + String.fromCharCode(39) + ",",
  String.fromCharCode(32,32,32,32,32,32) + "includedLanguages: " + String.fromCharCode(39) + "ar,en" + String.fromCharCode(39) + ",",
  String.fromCharCode(32,32,32,32,32,32) + "layout: google.translate.TranslateElement.InlineLayout.HORIZONTAL",
  String.fromCharCode(32,32,32,32) + "}, " + String.fromCharCode(39) + "google_translate_element" + String.fromCharCode(39) + ");",
  String.fromCharCode(32,32) + "}",
  '</script>',
  '<script src="//translate.google.com/translate_a/element.js?cb=googleTranslateElementInit"></script>',
].join("\n");

let changed = false;
if (html.indexOf("google_translate_element") === -1) {
  const idx = html.lastIndexOf("</body>");
  if (idx !== -1) {
    html = html.slice(0, idx) + widget + "\n" + html.slice(idx);
  } else {
    html = html + "\n" + widget + "\n";
  }
  changed = true;
}

return { filename: filename, html: html, changed: changed };

// Julie chatbot snippet (base64) — inserted verbatim before </body>.
const SNIPPET_B64 = '';
const snippet = Buffer.from(SNIPPET_B64, 'base64').toString('utf8');

const file = $('Julie: Get index.html').first().json;

let html;
if (file.content) {
  html = Buffer.from(String(file.content), 'base64').toString('utf8');
} else if (typeof file.data === 'string') {
  html = file.data;
} else {
  throw new Error('Could not read index.html content from GitHub get output.');
}

let updated;
if (html.includes('<!-- Julie Chatbot -->')) {
  updated = html;
} else if (html.includes('</body>')) {
  updated = html.replace('</body>', snippet + '\n</body>');
} else {
  updated = html + '\n' + snippet;
}

return [{ json: { fileContent: updated, sha: file.sha, already_present: html.includes('<!-- Julie Chatbot -->') } }];

var j = $json || {};
var content = String(j.content || j['Text to translate'] || j.text || '').trim();
var target = String(j.target_language || j['Target language'] || j.language || '').trim();
var valid = content.length > 0 && target.length > 0;
var system = 'You are a professional translator. Translate the user-provided text into ' + (target || 'the requested language') + '. Preserve the original meaning, tone, formatting and line breaks. Return ONLY the translated text with no preamble, notes, or explanation.';
var user = content;
return [{ json: { valid: valid, content: content, target_language: target, system: system, user: user } }];

var hub = $input.first().json || {};
var v = $('Translate: Validate Input').first().json || {};
var text = String(hub.text || '').trim();
var ok = hub.ok === true && text.length > 0;
var provider = hub.provider_used || 'none';
var title, message;
if (ok) {
  title = 'Translation complete (' + v.target_language + ')';
  message = text;
} else {
  title = 'Translation failed';
  message = 'Sorry, the translation could not be completed right now (provider: ' + provider + '). Please try again in a moment.';
}
return [{ json: { ok: ok, provider_used: provider, target_language: v.target_language, original_content: v.content, text: text, title: title, message: message } }];

var b = ($json && $json.body) ? $json.body : ($json || {});
var msg = String(b.message || b.text || b.chatInput || '').trim();
var system = "You are Julie, a warm and concise assistant for the hsndm.tech job-search website. Answer helpfully in 1-3 sentences. If you are unsure, say so briefly.";
var user = msg || '(no message provided)';
return [{ json: { message: msg, has_message: msg.length > 0, system: system, user: user } }];

var hub = $input.first().json || {};
var prep = $('Julie Chat Prep').first().json || {};
var text = String(hub.text || '').trim();
var reply;
if (!prep.has_message) { reply = "Hi! I'm Julie. Ask me anything about your job search."; }
else if (text.length) { reply = text; }
else { reply = "I'm here, but I'm having trouble thinking right now. Please try again in a moment."; }
return [{ json: { reply: reply } }];

var b = ($json && $json.body) ? $json.body : ($json || {});
var role = String(b.target_role || b.role || '').trim();
var email = String(b.email || '').trim();
var cv = String(b.cv_text || b.cv || '').trim();
var emailOk = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);
var valid = role.length > 0 && emailOk && cv.length > 0;
return [{ json: { valid: valid, target_role: role, email: email, cv_text: cv } }];

return [
  { json: { filename: "index.html" } },
  { json: { filename: "dashboard.html" } },
  { json: { filename: "cv.html" } },
];

const api = $json;
const filename = api.name || api.path;
const raw = (api.content || "").replace(/\n/g, "");
let html = "";
try { html = Buffer.from(raw, "base64").toString("utf8"); } catch (e) { html = ""; }
if (!html) { return { filename: filename, html: "", changed: false }; }
const before = html;
// Canonical chat endpoint is julie-chat; fix the joulie-chat typo everywhere.
html = html.split("webhook/joulie-chat").join("webhook/julie-chat");
const changed = html !== before;
return { filename: filename, html: html, changed: changed };
